/* Auditoria local somente leitura. Protótipos não equivalem a registros oficiais. */
(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;root.MartinsAuditoria36=api})(typeof window!=='undefined'?window:globalThis,function(){
'use strict';
const SPECS={planejamento:{key:'martins_planejamento_prototipo_v1',date:'dia',person:'pessoa',work:'obra',hours:'horas',category:null},frequencia:{key:'martins_frequencia_replicacao_prototipo_v1',date:'date',person:'person',work:'work',hours:'hours',category:null},vinculos:{key:'martins_vinculos_homologacao_v1',date:'data',person:'func',work:'obra',hours:'horas',category:'tipo'}};
const validDate=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s))&&new Date(s+'T12:00:00').toLocaleDateString('en-CA')===s;
function audit(input){const sources={},warnings=[],groups=new Map();for(const [type,s] of Object.entries(SPECS)){const rows=input[type];sources[type]={key:s.key,count:Array.isArray(rows)?rows.length:null};if(!Array.isArray(rows)){warnings.push(type+': coleção inválida');continue}rows.forEach((r,i)=>{if(!r||typeof r!=='object'||Array.isArray(r)){warnings.push(type+': linha '+(i+1)+' inválida');return}const date=r[s.date],person=String(r[s.person]??'').trim(),work=String(r[s.work]??'').trim(),hours=typeof r[s.hours]==='number'?r[s.hours]:Number(String(r[s.hours]??'').replace(',','.'));if(!validDate(date)||!person||!work||!Number.isFinite(hours)||hours<=0||hours>24){warnings.push(type+': linha '+(i+1)+' com campos inválidos');return}let category=type;if(type==='vinculos'){if(!['planejado','realizado'].includes(r.tipo)){warnings.push(type+': linha '+(i+1)+' com tipo inválido');return}category='vinculos_'+r.tipo}const key=JSON.stringify([date,person.toLocaleLowerCase('pt-BR')]);if(!groups.has(key))groups.set(key,{date,person,planning:0,frequency:0,linkedPlanning:0,linkedActual:0,workSets:{planejamento:new Set(),frequencia:new Set(),vinculos_planejado:new Set(),vinculos_realizado:new Set()},categories:{}});const g=groups.get(key);const field={planejamento:'planning',frequencia:'frequency',vinculos_planejado:'linkedPlanning',vinculos_realizado:'linkedActual'}[category];g[field]+=hours;g.workSets[category].add(work);g.categories[category]=(g.categories[category]||0)+1})}
const lines=[...groups.values()].map(g=>{const alerts=[];for(const [field,label] of [['planning','Planejamento'],['frequency','Frequência'],['linkedPlanning','Vínculos planejados'],['linkedActual','Vínculos realizados']])if(g[field]>8.00001)alerts.push(label+' excede 8h');if(g.planning&&g.frequency&&Math.abs(g.planning-g.frequency)>0.001)alerts.push('Horas planejadas ≠ frequência');if(g.linkedPlanning&&g.linkedActual&&Math.abs(g.linkedPlanning-g.linkedActual)>0.001)alerts.push('Vínculos: previsto ≠ realizado');if((g.frequency&&g.linkedActual)||(g.planning&&g.linkedPlanning))alerts.push('Fontes possivelmente sobrepostas: NÃO somar');return {date:g.date,person:g.person,planning:g.planning,frequency:g.frequency,linkedPlanning:g.linkedPlanning,linkedActual:g.linkedActual,alerts}}).sort((a,b)=>a.date.localeCompare(b.date)||a.person.localeCompare(b.person));return {version:36,readOnly:true,sources,warnings,lines}};
return {SPECS,audit};});
